begin;
create table public.lab_projects (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id), name text not null check(length(trim(name))>0), origin text not null check(origin in ('synthetic','user_unverified')), unique(id,owner_id,origin));
create table public.lab_explorations (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid(), project_id uuid not null, origin text not null, code text not null, depth_m numeric not null check(depth_m>0), unique(id,owner_id,origin), foreign key(project_id,owner_id,origin) references public.lab_projects(id,owner_id,origin));
create table public.lab_samples (id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid(), exploration_id uuid not null, origin text not null, code text not null, depth_from_m numeric not null check(depth_from_m>=0), depth_to_m numeric not null check(depth_to_m>depth_from_m), properties jsonb not null check(jsonb_typeof(properties)='object'), foreign key(exploration_id,owner_id,origin) references public.lab_explorations(id,owner_id,origin));
do $$ declare t text; begin foreach t in array array['lab_projects','lab_explorations','lab_samples'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); execute format('grant select, insert, update on public.%I to authenticated',t); execute format('create policy own_rows on public.%I for all to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()))',t); end loop; end $$;
commit;